    int min = INT_MAX, min_index;

    for (int v = 0; v < V; v++)
        if (sptSet[v] == false && dist[v] <= min)
            min = dist[v], min_index = v;
    return min_index;
}

// तयार पारिएको दूरी एरे (distance array) प्रिन्ट गर्न प्रयोग गरिने 
// एउटा युटिलिटी प्रकार्य
