HUMAN: सबै सहरहरूलाई जोड्ने न्यूनतम लागत गणना गर्न सक्ने Java कोड लेख्नुहोस्।

ASSISTANT: यसको उद्देश्य सबै सहरहरूलाई जोड्ने सबैभन्दा लागत-प्रभावी मार्ग स्थापना गर्नु हो। यो प्राप्त गर्न, हामीले प्रत्येक सहरलाई ग्राफमा नोडको रूपमा र सबै बिग्रिएका सडकहरूलाई एजको रूपमा मानेर सहरको नक्साको Minimum Spanning Tree (MST) निर्धारण गर्नुपर्छ। मार्गको कुल लागत Minimum Spanning Tree भित्रका एजहरूको मानहरूको योग हो।

```
// सबै सहरहरूलाई जोड्ने न्यूनतम लागत मार्ग पत्ता लगाउन Java कोड
import java.util.* ;

class GFG{

    // MST मा अहिलेसम्म समावेश नगरिएका नोडहरूमध्ये
    // न्यूनतम मान भएको नोड पत्ता लगाउने फंक्सन

    static int minNode(int n, int keyvals[], boolean mstset[])
    {
        int min_val = Integer.MAX_VALUE;
        int min_index = 0;

        // MST मा अहिलेसम्म समावेश नगरिएका नोडहरूका
        // सबै मानहरू मार्फत लूप चलाउनुहोस् र न्यूनतम मान भएको नोड फेला पार्नुहोस्।
        for(int i = 0; i < n; i++)
        {
            if (mstset[i] == false && keyvals[i] < min_val)
            {
                min_val = keyvals[i];
                min_index = i;
            }
        }
        return min_index;
    }

    // MST र MST को लागत पत्ता लगाउने फंक्सन।
    static void findCost(int n, int city[][])
    {

        // प्यारेन्ट नोडहरू भण्डारण गर्न एरे।
        int parent[] = new int[n];

        // प्रत्येक नोडको की भ्यालु भण्डारण गर्न एरे।
        int keyvals[] = new int[n];

        // नोड MST मा समावेश छ वा छैन भनेर संकेत गर्न बुलियन एरे।
        boolean mstset[] = new boolean[n];

        // सबै की भ्यालुहरूलाई अनन्तमा सेट गर्नुहोस् र कुनै पनि नोड MST मा समावेश गरिएको छैन।
        for(int i = 0; i < n; i++)
        {
            keyvals[i] = Integer.MAX_VALUE;
            mstset[i] = false;
        }

        // नोड 0 बाट MST फेला पार्न सुरु गर्नुहोस्।
        // नोड 0 को प्यारेन्ट कोही छैन र यसलाई -1 मा सेट गरिएको छ।
        // ० औं नोडबाट ० औं नोडमा पुग्नको लागि की भ्यालु वा न्यूनतम लागत ० हुन्छ।
        parent[0] = -1;
        keyvals[0] = 0;

        // MST को बाँकी n-1 नोडहरू फेला पार्नुहोस्।
        for(int i = 0; i < n - 1; i++)
        {    
            // पहिले MST मा अहिलेसम्म समावेश नगरिएका नोडहरू मध्ये न्यूनतम नोड पत्ता लगाउनुहोस्।
            int u = minNode(n, keyvals, mstset);

            // uth नोडलाई MST मा समावेश गर्नुहोस्।
            mstset[u] = true;

            // u का छिमेकी नोडहरूको मानहरू अपडेट गर्नुहोस् जुन अहिलेसम्म MST मा समावेश गरिएको छैन।
            for(int v = 0; v < n; v++)
            {
                if (city[u][v] > 0 && mstset[v] == false && city[u][v] < keyvals[v])
                {
                    keyvals[v] = city[u][v];
                    parent[v] = u;
                }
            }
        }

        // MST का एज मानहरू जोडेर लागत पत्ता लगाउनुहोस्।
        int cost = 0;
        for(int i = 1; i < n; i++)
            cost += city[parent[i]][i];

        System.out.println(cost);
    }

    // ड्राइभर कोड
    public static void main(String args[])
    {

        // इनपुट 1
        int n1 = 5;
        int city1[][] = { { 0, 1, 2, 3, 4 },
                        { 1, 0, 5, 0, 7 },
                        { 2, 5, 0, 6, 0 },
                        { 3, 0, 6, 0, 0 },
                        { 4, 7, 0, 0, 0 } };

        findCost(n1, city1);

        // इनपुट 2
        int n2 = 6;
        int city2[][] = { { 0, 1, 1, 100, 0, 0 },
                        { 1, 0, 1, 0, 0, 0 },
                        { 1, 1, 0, 0, 0, 0 },
                        { 100, 0, 0, 0, 2, 2 },
                        { 0, 0, 0, 2, 0, 2 },
                        { 0, 0, 0, 2, 2, 0 } };

        findCost(n2, city2);

    }
}
```

माथिको कोड कार्यान्वयन गरेपछि आउने आउटपुट यो हो:
```
10
106
```

टाइम कम्प्लेक्सिटीको सन्दर्भमा, Minimum Spanning Tree (MST) मा नयाँ नोड थप्नको लागि बाहिरी लूप n पटक चल्छ। प्रत्येक पुनरावृत्ति (iteration) को समयमा, न्यूनतम नोड फेला पार्न O(n) समय लाग्छ र u-औं नोडको छिमेकी नोडहरू अपडेट गर्न O(n) समय लाग्छ। नतिजाको रूपमा, समग्र टाइम कम्प्लेक्सिटी O(n^2) हुन्छ। सहायक स्पेस (auxiliary space) को लागी, एल्गोरिदमलाई O(n) स्पेस आवश्यक पर्दछ।

